window.SHIORI_DATA=window.SHIORI_DATA||{};SHIORI_DATA['n4_grammar']=[{"pattern":"〜（ら）れる (potential)","meaning":"can do; to be able to","formation":"Ru-verb: stem + られる (食べられる); U-verb: -u → -eru (書く→書ける); する→できる; 来る→来られる (こられる)","note":"The object is often marked with が instead of を. In casual speech ら is often dropped: 見れる, 来れる.","examples":[{"ja":"私は漢字が少し読めます。","en":"I can read a little kanji."},{"ja":"明日は早く来られますか。","en":"Can you come early tomorrow?"},{"ja":"弟は{泳|およ}げません。","en":"My little brother can't swim."}],"id":"n4g1"},{"pattern":"〜ことができる","meaning":"can do; to be able to","formation":"Verb dictionary form + ことができる; Noun + ができる","note":"More formal than the potential form. Used for ability and for what is possible or permitted.","examples":[{"ja":"兄はピアノを{弾|ひ}くことができます。","en":"My older brother can play the piano."},{"ja":"ここで写真を{撮|と}ることはできません。","en":"You cannot take photos here."},{"ja":"図書館では本を{三冊|さんさつ}まで借りることができます。","en":"At the library you can borrow up to three books."}],"id":"n4g2"},{"pattern":"〜（よ）う (volitional)","meaning":"let's ...; I'll ... (volitional form)","formation":"Ru-verb: stem + よう (食べよう); U-verb: -u → -ou (行く→行こう); する→しよう; 来る→来よう (こよう)","note":"Casual equivalent of 〜ましょう. Used to suggest doing something together; 〜（よ）うか asks 'shall we?'.","examples":[{"ja":"{一緒|いっしょ}に帰ろう。","en":"Let's go home together."},{"ja":"{疲|つか}れたね。ちょっと休もう。","en":"I'm tired, aren't you? Let's rest a bit."},{"ja":"{週末|しゅうまつ}、映画を見に行こうか。","en":"Shall we go see a movie this weekend?"}],"id":"n4g3"},{"pattern":"〜（よ）うと思う","meaning":"I think I'll ...; I'm thinking of doing","formation":"Verb volitional form + と思う / と思っている","note":"States the speaker's intention. 〜と思っている suggests an intention held for some time, and can describe others' plans.","examples":[{"ja":"夏休みに国へ帰ろうと思っています。","en":"I'm thinking of going back to my country during summer vacation."},{"ja":"今日は早く{寝|ね}ようと思います。","en":"I think I'll go to bed early today."},{"ja":"来年から日本語を勉強しようと思っています。","en":"I'm thinking of studying Japanese starting next year."}],"id":"n4g4"},{"pattern":"〜つもりだ","meaning":"to intend to; to plan to","formation":"Verb dictionary form / ない-form + つもりだ","note":"Expresses a firm personal intention. 〜ないつもりだ = intend not to; 〜つもりはない is a stronger denial.","examples":[{"ja":"来月、車を買うつもりです。","en":"I intend to buy a car next month."},{"ja":"もうタバコは{吸|す}わないつもりだ。","en":"I don't intend to smoke anymore."},{"ja":"大学を{卒業|そつぎょう}したら、何をするつもりですか。","en":"What do you plan to do after you graduate from university?"}],"id":"n4g5"},{"pattern":"〜{予定|よてい}だ","meaning":"to be scheduled to; to plan to","formation":"Verb dictionary form + 予定だ; Noun + の + 予定だ","note":"Describes an arranged schedule; more objective than つもり, which is a personal intention.","examples":[{"ja":"{会議|かいぎ}は三時に始まる{予定|よてい}です。","en":"The meeting is scheduled to begin at three."},{"ja":"来週、{大阪|おおさか}へ{出張|しゅっちょう}の{予定|よてい}です。","en":"I'm scheduled to go on a business trip to Osaka next week."},{"ja":"明日は{友達|ともだち}に会う{予定|よてい}があります。","en":"I have plans to meet a friend tomorrow."}],"id":"n4g6"},{"pattern":"〜てしまう","meaning":"to do completely; to do something regrettably","formation":"Verb て-form + しまう","note":"Shows completion or regret. Casual: てしまう→ちゃう, でしまう→じゃう (忘れちゃった, 飲んじゃった).","examples":[{"ja":"{宿題|しゅくだい}を{全部|ぜんぶ}やってしまいました。","en":"I finished all my homework."},{"ja":"{財布|さいふ}を{忘|わす}れてしまった。","en":"I (accidentally) forgot my wallet."},{"ja":"電車の中で{寝|ね}ちゃった。","en":"I fell asleep on the train."}],"id":"n4g7"},{"pattern":"〜ておく","meaning":"to do in advance; to leave something as it is","formation":"Verb て-form + おく","note":"Preparation for a future purpose, or leaving a state unchanged. Casual: ておく→とく (買っとく).","examples":[{"ja":"旅行の前に、ホテルを{予約|よやく}しておきます。","en":"I'll book the hotel before the trip."},{"ja":"{窓|まど}を開けておいてください。","en":"Please leave the window open."},{"ja":"ビールを{冷蔵庫|れいぞうこ}に入れておいた。","en":"I put the beer in the fridge (ahead of time)."}],"id":"n4g8"},{"pattern":"〜てある","meaning":"has been done (and remains that way)","formation":"Transitive verb て-form + ある","note":"Describes a state someone intentionally created; the object usually takes が. Compare intransitive 〜ている: ドアが開いている.","examples":[{"ja":"{壁|かべ}に地図が{貼|は}ってあります。","en":"A map has been put up on the wall."},{"ja":"{机|つくえ}の上にメモが{置|お}いてあります。","en":"A note has been left on the desk."},{"ja":"{晩|ばん}ご飯はもう作ってあるよ。","en":"Dinner has already been made."}],"id":"n4g9"},{"pattern":"〜てみる","meaning":"to try doing (to see what it's like)","formation":"Verb て-form + みる","note":"Written in hiragana. Means trying something out; for attempting something difficult, use 〜（よ）うとする.","examples":[{"ja":"この服を着てみてもいいですか。","en":"May I try on these clothes?"},{"ja":"日本の料理を作ってみました。","en":"I tried making Japanese food."},{"ja":"わからないなら、先生に聞いてみたら？","en":"If you don't understand, why not try asking the teacher?"}],"id":"n4g10"},{"pattern":"〜ていく","meaning":"to go on doing; to do and then go; a change continuing from now on","formation":"Verb て-form + いく","note":"Shows movement away from the speaker, or a change that will continue into the future. Casual: てく.","examples":[{"ja":"{傘|かさ}を持っていったほうがいいですよ。","en":"You'd better take an umbrella with you."},{"ja":"これから寒くなっていくでしょう。","en":"It will probably keep getting colder from now on."},{"ja":"駅まで歩いていきます。","en":"I'll walk to the station."}],"id":"n4g11"},{"pattern":"〜てくる","meaning":"to do and come back; a change up to now; to start to happen","formation":"Verb て-form + くる","note":"Shows movement toward the speaker, going somewhere and coming back, or a change that has developed up to now.","examples":[{"ja":"ちょっと飲み物を買ってきます。","en":"I'll just go buy a drink (and come back)."},{"ja":"だんだん{暖|あたた}かくなってきました。","en":"It has gradually gotten warmer."},{"ja":"雨が{降|ふ}ってきた。","en":"It's started to rain."}],"id":"n4g12"},{"pattern":"〜たら","meaning":"if; when; after","formation":"Verb / い-adjective past (た) form + ら; Noun / な-adjective + だったら","note":"The most versatile conditional; also 'when/after' for certain events. With a past result clause: 'when I did X, I found...'.","examples":[{"ja":"雨が{降|ふ}ったら、行きません。","en":"If it rains, I won't go."},{"ja":"駅に着いたら、電話してください。","en":"Please call me when you arrive at the station."},{"ja":"{窓|まど}を開けたら、{雪|ゆき}が{降|ふ}っていた。","en":"When I opened the window, it was snowing."}],"id":"n4g13"},{"pattern":"〜たらどうですか","meaning":"why don't you ...? (suggestion)","formation":"Verb た-form + らどうですか / らどう？","note":"Advice to the listener. Casual: 〜たら？ Use 〜たらいかがですか for more politeness.","examples":[{"ja":"少し休んだらどうですか。","en":"Why don't you rest a little?"},{"ja":"{熱|ねつ}があるなら、病院へ行ったら？","en":"If you have a fever, why don't you go to the hospital?"},{"ja":"先生に{相談|そうだん}したらどう？","en":"Why don't you talk it over with your teacher?"}],"id":"n4g14"},{"pattern":"〜ば","meaning":"if (conditional)","formation":"U-verb: -u → -eba (行けば); Ru-verb: stem + れば; い-adj: -い → -ければ; ない → なければ; Noun / な-adj + なら(ば)","note":"Focuses on the condition needed for the result. Usually not followed by a request or command when the condition is an action verb.","examples":[{"ja":"安ければ、買います。","en":"If it's cheap, I'll buy it."},{"ja":"この薬を飲めば、{治|なお}りますよ。","en":"If you take this medicine, you'll get better."},{"ja":"急げば、間に合います。","en":"If you hurry, you'll make it in time."}],"id":"n4g15"},{"pattern":"〜ばよかった","meaning":"I should have ...; I wish I had ...","formation":"Verb ば-form + よかった; negative: 〜なければよかった","note":"Expresses regret about the past, often followed by のに or なあ. 〜たらよかった has the same meaning.","examples":[{"ja":"もっと早く家を出ればよかった。","en":"I should have left home earlier."},{"ja":"あんなに食べなければよかった。","en":"I shouldn't have eaten so much."},{"ja":"{傘|かさ}を持ってくればよかったなあ。","en":"I wish I'd brought an umbrella."}],"id":"n4g16"},{"pattern":"〜と (conditional)","meaning":"when; if; whenever (natural or automatic result)","formation":"Verb / い-adjective dictionary form or ない-form + と; Noun / な-adjective + だ + と","note":"For natural results, habits, directions and discoveries. The result clause cannot be a request, wish or intention.","examples":[{"ja":"このボタンを{押|お}すと、お金が出ます。","en":"When you press this button, money comes out."},{"ja":"春になると、{桜|さくら}が{咲|さ}きます。","en":"When spring comes, the cherry blossoms bloom."},{"ja":"右に{曲|ま}がると、{郵便局|ゆうびんきょく}があります。","en":"If you turn right, there's a post office."}],"id":"n4g17"},{"pattern":"〜なら","meaning":"if (that's the case); if it's about ...","formation":"Verb / い-adjective plain form + なら; Noun / な-adjective + なら","note":"Responds to something just said, giving advice or an opinion based on it. Common for recommendations.","examples":[{"ja":"京都へ行くなら、{金閣寺|きんかくじ}を見たほうがいいですよ。","en":"If you're going to Kyoto, you should see Kinkakuji."},{"ja":"日本語の{辞書|じしょ}なら、あの店が安いです。","en":"If it's a Japanese dictionary you want, that shop is cheap."},{"ja":"{眠|ねむ}いなら、早く{寝|ね}なさい。","en":"If you're sleepy, go to bed early."}],"id":"n4g18"},{"pattern":"〜ても","meaning":"even if; even though","formation":"Verb て-form + も; い-adjective: -くても; Noun / な-adjective + でも","note":"The result happens regardless of the condition. With a past result: 〜ても〜なかった ('even though I..., it didn't...').","examples":[{"ja":"雨が{降|ふ}っても、試合はあります。","en":"Even if it rains, the game will be held."},{"ja":"高くても、このカメラが{欲|ほ}しいです。","en":"Even if it's expensive, I want this camera."},{"ja":"薬を飲んでも、{熱|ねつ}が下がらなかった。","en":"Even though I took medicine, my fever didn't go down."}],"id":"n4g19"},{"pattern":"いくら / どんなに / 何 + 〜ても","meaning":"no matter how (much) / what ...","formation":"いくら / どんなに / question word + て-form + も","note":"いくら and どんなに stress degree; with 何, 誰, どこ etc. it means 'no matter what/who/where'.","examples":[{"ja":"いくら考えても、答えがわかりません。","en":"No matter how much I think about it, I can't figure out the answer."},{"ja":"{彼|かれ}は何を食べても太らない。","en":"No matter what he eats, he doesn't gain weight."},{"ja":"どんなに{忙|いそが}しくても、毎日運動します。","en":"No matter how busy I am, I exercise every day."}],"id":"n4g20"},{"pattern":"〜なくてもいい","meaning":"don't have to; it's okay not to","formation":"Verb ない-form (drop い) + くてもいい","note":"Gives permission not to do something. More polite: 〜なくてもかまいません. Casual: 〜なくていい.","examples":[{"ja":"明日は来なくてもいいです。","en":"You don't have to come tomorrow."},{"ja":"{靴|くつ}を{脱|ぬ}がなくてもいいですよ。","en":"You don't need to take off your shoes."},{"ja":"{全部|ぜんぶ}食べなくてもいいよ。","en":"You don't have to eat it all."}],"id":"n4g21"},{"pattern":"〜てもかまわない","meaning":"it's all right if; I don't mind if","formation":"Verb て-form + もかまわない; い-adjective -くても / Noun・な-adjective + でも + かまわない","note":"A little more formal than 〜てもいい. Polite: 〜てもかまいません. Often written in kana (構わない).","examples":[{"ja":"ここに{座|すわ}ってもかまいませんか。","en":"Do you mind if I sit here?"},{"ja":"少し{遅|おく}れてもかまいません。","en":"It's fine if you're a little late."},{"ja":"古くてもかまわないので、安い自転車が{欲|ほ}しい。","en":"I want a cheap bicycle; I don't mind if it's old."}],"id":"n4g22"},{"pattern":"〜なきゃ / 〜なくちゃ","meaning":"have to; must (casual)","formation":"Verb ない-form (drop い) + きゃ / くちゃ (+ いけない / ならない)","note":"Casual contractions of 〜なければ and 〜なくては. The ending いけない / ならない is often dropped.","examples":[{"ja":"もう帰らなきゃ。","en":"I have to go home now."},{"ja":"明日までにレポートを書かなくちゃいけない。","en":"I have to write the report by tomorrow."},{"ja":"早く起きなきゃならないから、もう{寝|ね}るね。","en":"I have to get up early, so I'm going to bed now."}],"id":"n4g23"},{"pattern":"〜ないで (without doing)","meaning":"without doing; instead of doing","formation":"Verb ない-form + で","note":"Describes doing the main action without (or instead of) another. ずに is a more formal equivalent.","examples":[{"ja":"朝ご飯を食べないで学校へ行きました。","en":"I went to school without eating breakfast."},{"ja":"{傘|かさ}を持たないで出かけた。","en":"I went out without an umbrella."},{"ja":"{辞書|じしょ}を使わないで読んでみてください。","en":"Please try reading it without using a dictionary."}],"id":"n4g24"},{"pattern":"〜ほうがいい","meaning":"it's better to; you should / had better","formation":"Verb た-form + ほうがいい; Verb ない-form + ほうがいい","note":"Advice. Positive advice usually uses the た-form; negative uses the ない-form. Soften with と思います.","examples":[{"ja":"{熱|ねつ}があるなら、休んだほうがいいですよ。","en":"If you have a fever, you'd better rest."},{"ja":"夜{遅|おそ}くコーヒーを飲まないほうがいい。","en":"You shouldn't drink coffee late at night."},{"ja":"早く医者に行ったほうがいいと思います。","en":"I think you should go to the doctor soon."}],"id":"n4g25"},{"pattern":"〜やすい","meaning":"easy to do; tends to","formation":"Verb ます-stem + やすい","note":"Conjugates like an い-adjective (やすくて, やすかった). Can also mean 'tends to': 壊れやすい (breaks easily).","examples":[{"ja":"このペンは書きやすいです。","en":"This pen is easy to write with."},{"ja":"先生の説明はわかりやすかった。","en":"The teacher's explanation was easy to understand."},{"ja":"冬は{風邪|かぜ}をひきやすいです。","en":"It's easy to catch a cold in winter."}],"id":"n4g26"},{"pattern":"〜にくい","meaning":"hard to do; difficult to","formation":"Verb ます-stem + にくい","note":"Conjugates like an い-adjective. Describes practical difficulty; for personal inability, use the potential form.","examples":[{"ja":"この{靴|くつ}は歩きにくいです。","en":"These shoes are hard to walk in."},{"ja":"字が小さくて読みにくい。","en":"The writing is small and hard to read."},{"ja":"この薬は{苦|にが}くて飲みにくいです。","en":"This medicine is bitter and hard to take."}],"id":"n4g27"},{"pattern":"〜すぎる","meaning":"too much; to overdo","formation":"Verb ます-stem + すぎる; い-adjective (drop い) + すぎる; な-adjective + すぎる","note":"Conjugates as a ru-verb. Noun form すぎ: 飲みすぎ. Note いい → よすぎる, ない → なさすぎる.","examples":[{"ja":"{昨日|きのう}はお{酒|さけ}を飲みすぎました。","en":"I drank too much yesterday."},{"ja":"この問題は{難|むずか}しすぎます。","en":"This problem is too difficult."},{"ja":"この{部屋|へや}は{狭|せま}すぎて、ベッドが入らない。","en":"This room is too small; the bed won't fit."}],"id":"n4g28"},{"pattern":"〜し","meaning":"and also; what's more (listing reasons)","formation":"Plain form + し (Noun / な-adjective + だ + し)","note":"Lists several reasons or points, implying there may be more. Often used with も: 安いし、おいしいし.","examples":[{"ja":"この店は安いし、おいしいし、よく来ます。","en":"This place is cheap and the food is good, so I come here often."},{"ja":"今日は雨だし、寒いし、出かけたくない。","en":"It's raining and cold today, so I don't want to go out."},{"ja":"田中さんは親切だし、頭もいいです。","en":"Mr. Tanaka is kind, and smart too."}],"id":"n4g29"},{"pattern":"〜て / 〜くて / 〜で (reason)","meaning":"because; and so (cause of a feeling or result)","formation":"Verb て-form; い-adjective -くて; Noun / な-adjective + で; negative: 〜なくて","note":"Gives a cause, often of feelings or an inability. The second clause is usually not a request, command or intention.","examples":[{"ja":"ニュースを聞いて、びっくりしました。","en":"I was surprised to hear the news."},{"ja":"問題が{難|むずか}しくて、わかりませんでした。","en":"The problem was difficult, so I couldn't understand it."},{"ja":"病気で学校を休みました。","en":"I was absent from school because I was sick."}],"id":"n4g30"},{"pattern":"〜ので","meaning":"because; since","formation":"Plain form + ので; Noun / な-adjective + な + ので","note":"Softer and more polite than から; good for explanations and excuses. Casual speech: 〜んで.","examples":[{"ja":"頭が{痛|いた}いので、早く帰ってもいいですか。","en":"I have a headache, so may I go home early?"},{"ja":"明日は休みなので、{遅|おそ}くまで{寝|ね}ます。","en":"Tomorrow is my day off, so I'll sleep in."},{"ja":"道が{混|こ}んでいたので、{遅|おく}れました。","en":"The roads were crowded, so I was late."}],"id":"n4g31"},{"pattern":"〜のに (even though)","meaning":"even though; despite (with surprise or dissatisfaction)","formation":"Plain form + のに; Noun / な-adjective + な + のに","note":"Expresses frustration, regret or surprise at an unexpected result. Can end a sentence: 〜のに！","examples":[{"ja":"薬を飲んだのに、まだ{熱|ねつ}がある。","en":"Even though I took medicine, I still have a fever."},{"ja":"日曜日なのに、会社に行かなければならない。","en":"Even though it's Sunday, I have to go to work."},{"ja":"たくさん勉強したのに、試験に{落|お}ちた。","en":"Even though I studied a lot, I failed the exam."}],"id":"n4g32"},{"pattern":"〜のに (purpose)","meaning":"in order to; for (doing)","formation":"Verb dictionary form + のに; Noun + に","note":"Usually with 使う, いい, 便利, 必要, かかる (time / money). For general purposes, use ために.","examples":[{"ja":"このかばんは旅行に行くのに{便利|べんり}です。","en":"This bag is handy for traveling."},{"ja":"家を建てるのに三千万円かかりました。","en":"It cost 30 million yen to build the house."},{"ja":"はさみは紙を切るのに使います。","en":"Scissors are used for cutting paper."}],"id":"n4g33"},{"pattern":"〜んです / 〜のです","meaning":"explanatory: it's that ...; you see ...","formation":"Plain form + んです / のです; Noun / な-adjective + な + んです","note":"Gives or asks for an explanation, or adds emotion. Overuse can sound pushy. Casual: 〜んだ, 〜の？","examples":[{"ja":"どうしたんですか。","en":"What's wrong?"},{"ja":"おなかが{痛|いた}いんです。","en":"It's that I have a stomachache."},{"ja":"{昨日|きのう}はどうして来なかったんですか。","en":"Why didn't you come yesterday?"}],"id":"n4g34"},{"pattern":"〜けれども / 〜けど","meaning":"but; although","formation":"Plain or polite form + けれども / けど","note":"けれども is more formal; けど is casual. Also softens a request or introduces a topic: すみませんけど…","examples":[{"ja":"この料理は高いけど、おいしい。","en":"This dish is expensive, but it's good."},{"ja":"行きたいですけれども、時間がありません。","en":"I'd like to go, but I don't have time."},{"ja":"すみません、駅へ行きたいんですけど…。","en":"Excuse me, I'm trying to get to the station..."}],"id":"n4g35"},{"pattern":"〜そうだ (looks like)","meaning":"looks like; seems; looks about to","formation":"Verb ます-stem + そうだ; い-adjective (drop い) + そうだ; な-adjective + そうだ; いい→よさそう, ない→なさそう","note":"A guess from appearance. Not used for obvious visual traits like color. Before nouns: そうな (おいしそうなケーキ).","examples":[{"ja":"このケーキはおいしそうですね。","en":"This cake looks delicious."},{"ja":"雨が{降|ふ}りそうです。","en":"It looks like it's going to rain."},{"ja":"田中さんは元気がなさそうです。","en":"Mr. Tanaka seems to be feeling down."}],"id":"n4g36"},{"pattern":"〜そうだ (hearsay)","meaning":"I heard that; they say that","formation":"Plain form + そうだ (Noun / な-adjective + だ + そうだ)","note":"Reports information from another source, often named with によると. そうだ itself has no past or negative form.","examples":[{"ja":"{天気予報|てんきよほう}によると、明日は{雪|ゆき}が{降|ふ}るそうです。","en":"According to the weather forecast, it's going to snow tomorrow."},{"ja":"山田さんは来月{結婚|けっこん}するそうです。","en":"I heard Ms. Yamada is getting married next month."},{"ja":"あの店のラーメンはおいしいそうだ。","en":"I hear the ramen at that shop is good."}],"id":"n4g37"},{"pattern":"〜ようだ","meaning":"it seems that; it appears; like","formation":"Plain form + ようだ; Noun + の + ようだ; な-adjective + な + ようだ","note":"A judgment based on your own observation; more formal than みたい. Also for comparisons: 夢のようだ (like a dream).","examples":[{"ja":"{部屋|へや}に{誰|だれ}もいないようです。","en":"It seems there's nobody in the room."},{"ja":"{風邪|かぜ}をひいたようです。","en":"I seem to have caught a cold."},{"ja":"今日は春のような天気ですね。","en":"Today's weather is like spring, isn't it?"}],"id":"n4g38"},{"pattern":"〜みたいだ","meaning":"seems like; looks like; like (casual)","formation":"Plain form + みたいだ; Noun / な-adjective stem + みたいだ (no だ or な before it)","note":"Casual equivalent of ようだ. Before nouns: みたいな; as an adverb: みたいに.","examples":[{"ja":"外は寒いみたいだね。","en":"It looks like it's cold outside."},{"ja":"あの人は先生みたいだ。","en":"That person seems to be a teacher."},{"ja":"{彼|かれ}は{子供|こども}みたいに{笑|わら}った。","en":"He laughed like a child."}],"id":"n4g39"},{"pattern":"〜らしい","meaning":"apparently; I hear that; typical of","formation":"Plain form + らしい; Noun / な-adjective stem + らしい","note":"A conclusion based on what you heard or read. Noun + らしい can also mean 'typical of': 春らしい, 男らしい.","examples":[{"ja":"来週試験があるらしいよ。","en":"Apparently there's a test next week."},{"ja":"あのレストランは有名らしいです。","en":"That restaurant is apparently famous."},{"ja":"今日は春らしい{暖|あたた}かい日ですね。","en":"Today is a warm, spring-like day, isn't it?"}],"id":"n4g40"},{"pattern":"〜はずだ","meaning":"should be; is expected to (logically)","formation":"Plain form + はずだ; Noun + の + はずだ; な-adjective + な + はずだ","note":"The speaker's confident expectation based on facts. Not for advice; for that, use 〜ほうがいい.","examples":[{"ja":"田中さんはもう家に着いているはずです。","en":"Mr. Tanaka should be home by now."},{"ja":"{会議|かいぎ}は三時に終わるはずだ。","en":"The meeting should end at three."},{"ja":"{彼|かれ}は日本に十年住んでいたから、日本語が上手なはずです。","en":"He lived in Japan for ten years, so his Japanese should be good."}],"id":"n4g41"},{"pattern":"〜はずがない","meaning":"there's no way that; it can't be that","formation":"Plain form + はずがない; Noun + の + はずがない; な-adjective + な + はずがない","note":"Strong denial based on reasoning. Compare 〜ないはずだ ('should not'), which is weaker.","examples":[{"ja":"あんなに{練習|れんしゅう}したんだから、{負|ま}けるはずがない。","en":"We practiced so hard; there's no way we'll lose."},{"ja":"{彼|かれ}がそんなことを言うはずがありません。","en":"There's no way he would say something like that."},{"ja":"{昨日|きのう}買ったばかりだから、{壊|こわ}れているはずがない。","en":"I only bought it yesterday, so it can't be broken."}],"id":"n4g42"},{"pattern":"〜かもしれない","meaning":"might; maybe; perhaps","formation":"Plain form + かもしれない; Noun / な-adjective stem + かもしれない","note":"Roughly 50% certainty or less. Polite: かもしれません. Casual: かも.","examples":[{"ja":"午後から雨が{降|ふ}るかもしれません。","en":"It might rain from the afternoon."},{"ja":"{財布|さいふ}は車の中かもしれない。","en":"My wallet might be in the car."},{"ja":"明日のパーティーには行けないかも。","en":"I might not be able to go to the party tomorrow."}],"id":"n4g43"},{"pattern":"〜だろう","meaning":"probably; I suppose (plain form of でしょう)","formation":"Plain form + だろう; Noun / な-adjective stem + だろう","note":"Common in writing and men's speech; often with たぶん or きっと. With rising intonation it seeks agreement ('right?').","examples":[{"ja":"明日はたぶん{晴|は}れるだろう。","en":"It will probably be sunny tomorrow."},{"ja":"{彼|かれ}はきっと来ないだろう。","en":"He probably won't come."},{"ja":"この問題は{子供|こども}には{難|むずか}しいだろうと思う。","en":"I think this problem is probably difficult for children."}],"id":"n4g44"},{"pattern":"Question word + 〜か (embedded question)","meaning":"(who / what / where etc.) ... — question inside a sentence","formation":"Question word + plain form + か; Noun / な-adjective (drop だ) + か","note":"Embeds a question in a larger sentence, often with 知っている, わかる, 教える, 覚えている.","examples":[{"ja":"{会議|かいぎ}が何時に始まるか知っていますか。","en":"Do you know what time the meeting starts?"},{"ja":"どこに{鍵|かぎ}を{置|お}いたか{忘|わす}れてしまった。","en":"I forgot where I put the key."},{"ja":"{誰|だれ}が来るか教えてください。","en":"Please tell me who is coming."}],"id":"n4g45"},{"pattern":"〜かどうか","meaning":"whether or not","formation":"Plain form + かどうか; Noun / な-adjective (drop だ) + かどうか","note":"Embeds a yes/no question (one with no question word) in a sentence.","examples":[{"ja":"明日行けるかどうか、まだわかりません。","en":"I don't know yet whether I can go tomorrow."},{"ja":"この答えが正しいかどうか{調|しら}べてください。","en":"Please check whether this answer is correct."},{"ja":"山田さんが元気かどうか聞いてみます。","en":"I'll ask whether Mr. Yamada is doing well."}],"id":"n4g46"},{"pattern":"〜ために","meaning":"in order to; for the sake of; because of","formation":"Verb dictionary form + ために; Noun + の + ために","note":"Purpose with intentional verbs and the same subject. With nouns like 事故 it means 'because of'. Compare ように.","examples":[{"ja":"日本の大学に入るために、毎日勉強しています。","en":"I'm studying every day to get into a Japanese university."},{"ja":"家族のために働いています。","en":"I'm working for my family."},{"ja":"{事故|じこ}のために、電車が{遅|おく}れました。","en":"The train was delayed because of an accident."}],"id":"n4g47"},{"pattern":"〜ように (so that)","meaning":"so that; in order that","formation":"Verb dictionary form / ない-form + ように","note":"Used with potential, non-intentional or negative verbs (見える, わかる, 〜ない). The two clauses can have different subjects.","examples":[{"ja":"後ろの人にも聞こえるように、大きい声で話してください。","en":"Please speak loudly so that the people at the back can hear too."},{"ja":"{風邪|かぜ}をひかないように、コートを着ていきます。","en":"I'll wear a coat so I don't catch a cold."},{"ja":"{忘|わす}れないように、メモしておきます。","en":"I'll make a note so I don't forget."}],"id":"n4g48"},{"pattern":"〜ようになる","meaning":"to come to (be able to); to start doing (gradual change)","formation":"Verb dictionary form / potential form + ようになる","note":"Shows a change in ability or habit over time. The negative change is usually 〜なくなる (読めなくなった).","examples":[{"ja":"日本語が話せるようになりました。","en":"I've become able to speak Japanese."},{"ja":"毎朝走るようになった。","en":"I've started running every morning."},{"ja":"{娘|むすめ}は野菜を食べるようになりました。","en":"My daughter has started eating vegetables."}],"id":"n4g49"},{"pattern":"〜ようにする","meaning":"to try to; to make sure to","formation":"Verb dictionary form / ない-form + ようにする","note":"Making an effort to do something. 〜ようにしている describes an ongoing habit.","examples":[{"ja":"毎日野菜を食べるようにしています。","en":"I make a point of eating vegetables every day."},{"ja":"夜{遅|おそ}くまでゲームをしないようにします。","en":"I'll try not to play games until late at night."},{"ja":"明日は{遅|おく}れないようにしてください。","en":"Please make sure not to be late tomorrow."}],"id":"n4g50"},{"pattern":"〜ように言う","meaning":"to tell (someone) to do","formation":"Verb dictionary form / ない-form + ように言う (also 頼む, 伝える)","note":"Reports an instruction or request indirectly. The person told is marked with に.","examples":[{"ja":"母は弟に早く{寝|ね}るように言いました。","en":"My mother told my brother to go to bed early."},{"ja":"医者にお{酒|さけ}を飲まないように言われた。","en":"The doctor told me not to drink alcohol."},{"ja":"田中さんに電話するように{伝|つた}えてください。","en":"Please tell Mr. Tanaka to call."}],"id":"n4g51"},{"pattern":"〜ことにする","meaning":"to decide to","formation":"Verb dictionary form / ない-form + ことにする","note":"The speaker's own decision. 〜ことにしている means a personal rule or habit.","examples":[{"ja":"来年、日本へ{留学|りゅうがく}することにしました。","en":"I've decided to study abroad in Japan next year."},{"ja":"今日からお{菓子|かし}を食べないことにする。","en":"Starting today, I'm going to stop eating sweets."},{"ja":"毎朝六時に起きることにしています。","en":"I make it a rule to get up at six every morning."}],"id":"n4g52"},{"pattern":"〜ことになる","meaning":"it has been decided that; it turns out that","formation":"Verb dictionary form / ない-form + ことになる","note":"A decision made by others or by circumstances. 〜ことになっている means an established rule.","examples":[{"ja":"来月、{大阪|おおさか}に引っ{越|こ}すことになりました。","en":"It's been decided that I'll move to Osaka next month."},{"ja":"{会議|かいぎ}は金曜日にすることになった。","en":"It was decided that the meeting will be on Friday."},{"ja":"この{部屋|へや}では{靴|くつ}を{脱|ぬ}ぐことになっています。","en":"The rule is that you take your shoes off in this room."}],"id":"n4g53"},{"pattern":"〜ことがある","meaning":"there are times when; sometimes","formation":"Verb dictionary form / ない-form + ことがある","note":"Different from 〜たことがある ('have done before'). Often used with ときどき or たまに.","examples":[{"ja":"朝ご飯を食べないことがあります。","en":"There are times when I don't eat breakfast."},{"ja":"たまに会社まで歩いて行くことがある。","en":"Occasionally I walk to the office."},{"ja":"この道は夜、{危|あぶ}ないことがあります。","en":"This road can be dangerous at night."}],"id":"n4g54"},{"pattern":"〜（よ）うとする","meaning":"to try to; to be about to","formation":"Verb volitional form + とする","note":"An attempt (often unsuccessful) or the moment just before an action. Compare 〜てみる (try out).","examples":[{"ja":"{寝|ね}ようとしたとき、電話が{鳴|な}った。","en":"Just as I was about to go to sleep, the phone rang."},{"ja":"{窓|まど}を開けようとしましたが、開きませんでした。","en":"I tried to open the window, but it wouldn't open."},{"ja":"赤ちゃんが立とうとしています。","en":"The baby is trying to stand up."}],"id":"n4g55"},{"pattern":"〜場合は","meaning":"in the case of; if","formation":"Plain form + 場合は; Noun + の + 場合は; な-adjective + な + 場合は","note":"Formal; common in instructions and rules. Not used for a single event that already happened.","examples":[{"ja":"火事の場合は、エレベーターを使わないでください。","en":"In case of fire, do not use the elevator."},{"ja":"{遅|おく}れる場合は、{連絡|れんらく}してください。","en":"If you're going to be late, please let us know."},{"ja":"雨の場合は、運動会は中止です。","en":"In case of rain, the sports day will be canceled."}],"id":"n4g56"},{"pattern":"〜まま","meaning":"as it is; leaving (a state) unchanged","formation":"Verb た-form / ない-form + まま; Noun + の + まま; この / その + まま","note":"Something stays in the same state while something else happens, often when it normally shouldn't.","examples":[{"ja":"{靴|くつ}を{履|は}いたまま{部屋|へや}に入らないでください。","en":"Please don't enter the room with your shoes on."},{"ja":"電気をつけたまま{寝|ね}てしまった。","en":"I fell asleep with the light on."},{"ja":"このままでいいです。","en":"It's fine as it is."}],"id":"n4g57"},{"pattern":"〜るところだ (about to)","meaning":"about to do; just going to","formation":"Verb dictionary form + ところだ","note":"The action is just about to start. Often used with これから or 今から.","examples":[{"ja":"これから出かけるところです。","en":"I'm just about to go out."},{"ja":"今から{晩|ばん}ご飯を食べるところだ。","en":"I'm just about to eat dinner."},{"ja":"{授業|じゅぎょう}が始まるところだから、急ごう。","en":"Class is about to start, so let's hurry."}],"id":"n4g58"},{"pattern":"〜ているところだ","meaning":"in the middle of doing","formation":"Verb て-form + いるところだ","note":"Stresses being right in the middle of an action at this moment.","examples":[{"ja":"今、{宿題|しゅくだい}をしているところです。","en":"I'm in the middle of doing my homework."},{"ja":"母は料理を作っているところだ。","en":"My mother is in the middle of cooking."},{"ja":"その問題は今{調|しら}べているところです。","en":"We're looking into that problem right now."}],"id":"n4g59"},{"pattern":"〜たところだ","meaning":"have just done","formation":"Verb た-form + ところだ","note":"Stresses the moment right after an action. Compare 〜たばかり, which can cover a longer time.","examples":[{"ja":"今、家に帰ってきたところです。","en":"I've just come home."},{"ja":"{授業|じゅぎょう}が終わったところだ。","en":"Class has just ended."},{"ja":"ちょうど今、駅に着いたところです。","en":"I've just this moment arrived at the station."}],"id":"n4g60"},{"pattern":"〜たばかり","meaning":"just did (recently)","formation":"Verb た-form + ばかり","note":"The speaker feels it was recent, even if some time has passed: 先月来たばかり. Often 〜たばかりなので.","examples":[{"ja":"日本に来たばかりなので、まだ日本語がよくわかりません。","en":"I've only just come to Japan, so I don't understand Japanese well yet."},{"ja":"さっき食べたばかりだから、おなかがいっぱいです。","en":"I just ate, so I'm full."},{"ja":"この車は先月買ったばかりです。","en":"I only bought this car last month."}],"id":"n4g61"},{"pattern":"〜間 / 〜間に","meaning":"while; during (the whole time) / while (at some point)","formation":"Verb ている-form / dictionary form + 間(に); Noun + の + 間(に)","note":"間 = throughout the whole period; 間に = at some point within the period.","examples":[{"ja":"夏休みの間、ずっと国に帰っていました。","en":"I was back in my home country for the whole summer vacation."},{"ja":"母が{寝|ね}ている間に、{部屋|へや}を{掃除|そうじ}しました。","en":"I cleaned the room while my mother was sleeping."},{"ja":"{留守|るす}の間に{友達|ともだち}が来たそうです。","en":"Apparently a friend came by while I was out."}],"id":"n4g62"},{"pattern":"〜までに","meaning":"by (a deadline)","formation":"Noun (time) + までに; Verb dictionary form + までに","note":"Marks a deadline. Compare まで ('until'), used with an action that continues up to that point.","examples":[{"ja":"金曜日までにレポートを出してください。","en":"Please hand in the report by Friday."},{"ja":"五時までに帰ります。","en":"I'll be back by five."},{"ja":"暗くなるまでに家に着きたい。","en":"I want to get home before it gets dark."}],"id":"n4g63"},{"pattern":"〜とおりに","meaning":"just as; in the same way as","formation":"Verb dictionary form / た-form + とおりに; Noun + の + とおりに; Noun + どおりに","note":"Doing something exactly as shown, said or planned. Also written 通りに.","examples":[{"ja":"先生が言ったとおりに書いてください。","en":"Please write it exactly as the teacher said."},{"ja":"地図のとおりに行ったら、すぐわかりました。","en":"When I followed the map, I found it right away."},{"ja":"{予定|よてい}どおりに{会議|かいぎ}が始まった。","en":"The meeting started as scheduled."}],"id":"n4g64"},{"pattern":"〜（ら）れる (passive)","meaning":"to be done (to); passive voice","formation":"Ru-verb: stem + られる; U-verb: -u → -areru (書く→書かれる); する→される; 来る→来られる (こられる)","note":"The doer is marked with に. The 'suffering passive' shows the subject was troubled: 雨に降られた.","examples":[{"ja":"先生に{褒|ほ}められました。","en":"I was praised by the teacher."},{"ja":"雨に{降|ふ}られて、服がぬれてしまった。","en":"I got caught in the rain and my clothes got wet."},{"ja":"この{寺|てら}は六百年前に建てられました。","en":"This temple was built 600 years ago."}],"id":"n4g65"},{"pattern":"〜（さ）せる (causative)","meaning":"to make / let (someone) do","formation":"Ru-verb: stem + させる; U-verb: -u → -aseru (書く→書かせる); する→させる; 来る→来させる (こさせる)","note":"Context decides 'make' or 'let'. The person made to act takes に (or を with intransitive verbs).","examples":[{"ja":"母は弟に野菜を食べさせました。","en":"My mother made my brother eat vegetables."},{"ja":"{子供|こども}を{公園|こうえん}で{遊|あそ}ばせます。","en":"I let the children play in the park."},{"ja":"{部長|ぶちょう}は私に{会議|かいぎ}の{準備|じゅんび}をさせた。","en":"The department manager had me prepare for the meeting."}],"id":"n4g66"},{"pattern":"〜（さ）せられる (causative-passive)","meaning":"to be made to do (against one's will)","formation":"Ru-verb: stem + させられる; U-verb: -u → -aserareru, often shortened to -asareru (飲まされる); する→させられる; 来る→来させられる","note":"The subject is forced to do something unwanted. The person forcing is marked with に.","examples":[{"ja":"{子供|こども}のころ、母に{嫌|きら}いな野菜を食べさせられました。","en":"When I was a child, my mother made me eat vegetables I hated."},{"ja":"{先輩|せんぱい}にお{酒|さけ}を飲まされた。","en":"I was made to drink alcohol by an older student."},{"ja":"一時間も待たされました。","en":"I was kept waiting for a whole hour."}],"id":"n4g67"},{"pattern":"〜させてください","meaning":"please let me do","formation":"Verb causative て-form + ください","note":"Politely asks permission to do something yourself. Humbler: 〜させていただけませんか.","examples":[{"ja":"ここは私に{払|はら}わせてください。","en":"Please let me pay this time."},{"ja":"少し考えさせてください。","en":"Please let me think about it a little."},{"ja":"今日は早く帰らせてください。","en":"Please let me go home early today."}],"id":"n4g68"},{"pattern":"あげる / くれる / もらう","meaning":"to give / to give (to me) / to receive","formation":"Giver は Receiver に Thing を あげる; Giver が (私に) Thing を くれる; Receiver は Giver に/から Thing を もらう","note":"くれる is only for giving toward the speaker or their in-group. Polite forms: さしあげる, くださる, いただく.","examples":[{"ja":"私は{友達|ともだち}に花をあげました。","en":"I gave my friend some flowers."},{"ja":"姉が私に時計をくれました。","en":"My older sister gave me a watch."},{"ja":"{誕生日|たんじょうび}に父から自転車をもらった。","en":"I got a bicycle from my father for my birthday."}],"id":"n4g69"},{"pattern":"〜てあげる","meaning":"to do something for someone","formation":"Verb て-form + あげる","note":"The speaker (or in-group) does a favor for others. Can sound condescending, so avoid it directly toward superiors.","examples":[{"ja":"妹に本を読んであげました。","en":"I read a book to my little sister."},{"ja":"{友達|ともだち}に駅までの道を教えてあげた。","en":"I showed my friend the way to the station."},{"ja":"{祖母|そぼ}の{荷物|にもつ}を持ってあげました。","en":"I carried my grandmother's bags for her."}],"id":"n4g70"},{"pattern":"〜てくれる","meaning":"(someone) does something for me / us","formation":"Verb て-form + くれる","note":"The receiver is the speaker or their in-group, and it shows gratitude. With superiors: 〜てくださる.","examples":[{"ja":"{友達|ともだち}が引っ{越|こ}しを{手伝|てつだ}ってくれました。","en":"My friend helped me move."},{"ja":"父が自転車を{直|なお}してくれた。","en":"My father fixed my bicycle for me."},{"ja":"先生が作文を{直|なお}してくださいました。","en":"The teacher kindly corrected my essay."}],"id":"n4g71"},{"pattern":"〜てもらう","meaning":"to have someone do something (for me); to receive a favor","formation":"Verb て-form + もらう","note":"The person doing the favor is marked with に. Humble form: 〜ていただく.","examples":[{"ja":"姉に{宿題|しゅくだい}を{手伝|てつだ}ってもらいました。","en":"My older sister helped me with my homework."},{"ja":"{友達|ともだち}に写真を{撮|と}ってもらった。","en":"I had a friend take a picture of me."},{"ja":"先生に日本語を教えていただきました。","en":"The teacher kindly taught me Japanese."}],"id":"n4g72"},{"pattern":"〜てくれませんか / 〜てもらえませんか","meaning":"could you (please) do ...?","formation":"Verb て-form + くれませんか / もらえませんか","note":"Softer than 〜てください; もらえませんか is slightly more polite. Casual: 〜てくれない？","examples":[{"ja":"ちょっと{手伝|てつだ}ってくれませんか。","en":"Could you help me for a moment?"},{"ja":"もう少しゆっくり話してもらえませんか。","en":"Could you speak a little more slowly?"},{"ja":"{窓|まど}を{閉|し}めてくれない？","en":"Could you close the window?"}],"id":"n4g73"},{"pattern":"〜ていただけませんか","meaning":"could you possibly do ...? (very polite request)","formation":"Verb て-form + いただけませんか (also 〜てくださいませんか)","note":"A very polite request to superiors or strangers. 〜ていただけないでしょうか is even more polite.","examples":[{"ja":"すみません、写真を{撮|と}っていただけませんか。","en":"Excuse me, could you possibly take our picture?"},{"ja":"この作文をチェックしていただけませんか。","en":"Could you please check this essay?"},{"ja":"駅までの道を教えてくださいませんか。","en":"Would you kindly tell me the way to the station?"}],"id":"n4g74"},{"pattern":"〜てほしい","meaning":"to want (someone) to do","formation":"Verb て-form + ほしい; negative: 〜ないでほしい","note":"The person you want to act is marked with に. Can sound demanding if said directly to superiors.","examples":[{"ja":"母にはいつまでも元気でいてほしい。","en":"I want my mother to stay healthy forever."},{"ja":"{友達|ともだち}にパーティーに来てほしいです。","en":"I want my friends to come to the party."},{"ja":"{部屋|へや}でタバコを{吸|す}わないでほしい。","en":"I'd like you not to smoke in the room."}],"id":"n4g75"},{"pattern":"〜がる","meaning":"to show signs of (a feeling); to act (scared, cold, etc.)","formation":"い-adjective (drop い) + がる; な-adjective + がる","note":"Describes other people's feelings from outward signs; not used about yourself. Usually 〜がっている.","examples":[{"ja":"妹は犬を{怖|こわ}がっています。","en":"My little sister is scared of dogs."},{"ja":"{子供|こども}が寒がっているから、{窓|まど}を{閉|し}めよう。","en":"The child seems cold, so let's close the window."},{"ja":"弟は新しいゲームを{欲|ほ}しがっている。","en":"My little brother wants a new game."}],"id":"n4g76"},{"pattern":"〜たがる","meaning":"(someone else) wants to do","formation":"Verb ます-stem + たがる","note":"Third-person version of 〜たい; usually 〜たがっている. The object takes を.","examples":[{"ja":"{息子|むすこ}は{動物園|どうぶつえん}に行きたがっています。","en":"My son wants to go to the zoo."},{"ja":"{彼女|かのじょ}は日本に{留学|りゅうがく}したがっている。","en":"She wants to study abroad in Japan."},{"ja":"{子供|こども}は薬を飲みたがらない。","en":"Children don't like to take medicine."}],"id":"n4g77"},{"pattern":"お〜になる","meaning":"honorific: (a respected person) does","formation":"お + Verb ます-stem + になる","note":"Raises the subject's action. Verbs with special honorific forms (行く, 見る, 言う…) use those instead.","examples":[{"ja":"社長はもうお帰りになりました。","en":"The company president has already gone home."},{"ja":"先生、この本をお読みになりましたか。","en":"Professor, have you read this book?"},{"ja":"{部長|ぶちょう}は何時にお着きになりますか。","en":"What time will the department manager arrive?"}],"id":"n4g78"},{"pattern":"Special honorific verbs (いらっしゃる, おっしゃる…)","meaning":"honorific verbs for the actions of respected people","formation":"いる / 行く / 来る→いらっしゃる; 言う→おっしゃる; 食べる / 飲む→召し上がる; する→なさる; 見る→ご覧になる; くれる→くださる","note":"いらっしゃる, おっしゃる, なさる and くださる have irregular ます-forms: いらっしゃいます, おっしゃいます, etc.","examples":[{"ja":"先生は今、教室にいらっしゃいます。","en":"The teacher is in the classroom now."},{"ja":"社長がそうおっしゃいました。","en":"The company president said so."},{"ja":"どうぞ{召|め}し上がってください。","en":"Please help yourself (to the food)."}],"id":"n4g79"},{"pattern":"お〜する","meaning":"humble: I (humbly) do (for you)","formation":"お + Verb ます-stem + する; ご + する-noun + する (ご連絡する)","note":"Lowers the speaker's own action toward a respected person. More humble: お〜いたす.","examples":[{"ja":"お{荷物|にもつ}をお持ちします。","en":"Let me carry your bags."},{"ja":"後でお電話します。","en":"I'll call you later."},{"ja":"{会議|かいぎ}の時間をご{連絡|れんらく}します。","en":"I'll let you know the meeting time."}],"id":"n4g80"},{"pattern":"Special humble verbs (まいる, いたす…)","meaning":"humble verbs for the speaker's own actions","formation":"行く / 来る→まいる; いる→おる; 言う→申す; する→いたす; 食べる / もらう→いただく; 見る→拝見する; 会う→お目にかかる","note":"Used for the speaker's or in-group's actions. Common in self-introductions and business: 田中と申します.","examples":[{"ja":"はじめまして、田中と{申|もう}します。","en":"Nice to meet you. My name is Tanaka."},{"ja":"明日、十時にまいります。","en":"I will come at ten tomorrow."},{"ja":"父は今、出かけております。","en":"My father is out at the moment."}],"id":"n4g81"},{"pattern":"お〜ください","meaning":"please do (honorific request)","formation":"お + Verb ます-stem + ください; ご + する-noun + ください","note":"More polite than 〜てください; common in shops, announcements and signs.","examples":[{"ja":"こちらでお待ちください。","en":"Please wait here."},{"ja":"どうぞお入りください。","en":"Please come in."},{"ja":"何でもご{相談|そうだん}ください。","en":"Please feel free to ask us about anything."}],"id":"n4g82"},{"pattern":"〜でございます / ございます","meaning":"very polite 'to be' / 'to have, there is'","formation":"Noun + でございます (= です); ございます (= あります)","note":"Typical of shop staff, receptionists and formal announcements toward customers.","examples":[{"ja":"お手洗いは{二階|にかい}でございます。","en":"The restroom is on the second floor."},{"ja":"何かご質問はございますか。","en":"Do you have any questions?"},{"ja":"こちらが新しいメニューでございます。","en":"This is our new menu."}],"id":"n4g83"},{"pattern":"〜なさい","meaning":"do ...! (gentle command)","formation":"Verb ます-stem + なさい","note":"Used by parents to children, teachers to students, and in test instructions. Never toward superiors.","examples":[{"ja":"早く{寝|ね}なさい。","en":"Go to bed now."},{"ja":"食べる前に手を洗いなさい。","en":"Wash your hands before you eat."},{"ja":"{次|つぎ}の質問に答えなさい。","en":"Answer the following questions."}],"id":"n4g84"},{"pattern":"{命令形|めいれいけい} (imperative form)","meaning":"do it! (blunt command)","formation":"U-verb: -u → -e (行く→行け); Ru-verb: stem + ろ (食べろ); する→しろ; 来る→来い (こい)","note":"Very blunt: used in emergencies, sports cheering, rough male speech, and when quoting orders (〜ろと言われた).","examples":[{"ja":"{危|あぶ}ない！{逃|に}げろ！","en":"Look out! Run!"},{"ja":"{頑張|がんば}れ！","en":"Go for it! / Hang in there!"},{"ja":"早く来い！","en":"Get over here, quick!"}],"id":"n4g85"},{"pattern":"〜な (prohibition)","meaning":"don't do! (blunt prohibition)","formation":"Verb dictionary form + な","note":"Strong and blunt; seen on signs and in rough male speech. Don't confuse with the soft sentence-ending な(あ).","examples":[{"ja":"ここに車を止めるな。","en":"Don't park your car here."},{"ja":"{触|さわ}るな！","en":"Don't touch!"},{"ja":"{心配|しんぱい}するな。","en":"Don't worry."}],"id":"n4g86"},{"pattern":"〜という","meaning":"called; named; (the content) that","formation":"Noun + という + Noun; Plain form + という + Noun (話, ニュース, こと)","note":"Introduces a name the listener may not know ('a ... called ...'), or gives the content of 話, ニュース, etc.","examples":[{"ja":"「さくら」という店を知っていますか。","en":"Do you know a shop called 'Sakura'?"},{"ja":"これは何という花ですか。","en":"What is this flower called?"},{"ja":"田中さんが{結婚|けっこん}するという話を聞きました。","en":"I heard that Mr. Tanaka is getting married."}],"id":"n4g87"},{"pattern":"〜と言っていた","meaning":"(someone) said that","formation":"Plain form + と言っていた / と言っていました","note":"Reports what a third person said; natural when passing on a message.","examples":[{"ja":"田中さんは明日来ないと言っていました。","en":"Mr. Tanaka said he won't come tomorrow."},{"ja":"先生が試験は{難|むずか}しくないと言っていたよ。","en":"The teacher said the exam isn't difficult."},{"ja":"母がよろしくと言っていました。","en":"My mother sends her regards."}],"id":"n4g88"},{"pattern":"〜って","meaning":"casual quote marker: (someone) says; I heard; as for","formation":"Plain form + って; Noun + って","note":"Casual replacement for と, と言う, という or は. 〜んだって = 'I heard that'. Spoken language only.","examples":[{"ja":"山田さん、今日は休むって。","en":"Yamada says she's taking today off."},{"ja":"明日、テストがあるんだって。","en":"I heard there's a test tomorrow."},{"ja":"「すき{焼|や}き」って何ですか。","en":"What is 'sukiyaki'?"}],"id":"n4g89"},{"pattern":"〜かな","meaning":"I wonder (if)","formation":"Plain form + かな; Noun / な-adjective stem + かな","note":"Casual, self-directed wondering. 〜ないかな can express a wish: 早く来ないかな.","examples":[{"ja":"明日は{晴|は}れるかな。","en":"I wonder if it'll be sunny tomorrow."},{"ja":"田中さんはどこに行ったのかな。","en":"I wonder where Mr. Tanaka went."},{"ja":"早く夏休みにならないかな。","en":"I wish summer vacation would hurry up and come."}],"id":"n4g90"},{"pattern":"〜かしら","meaning":"I wonder (feminine)","formation":"Plain form + かしら; Noun / な-adjective stem + かしら","note":"Same meaning as かな, but mainly used by women and sounds soft, somewhat old-fashioned.","examples":[{"ja":"明日は雨かしら。","en":"I wonder if it'll rain tomorrow."},{"ja":"この服、私に{似合|にあ}うかしら。","en":"I wonder if this outfit suits me."},{"ja":"{彼|かれ}、もう着いたかしら。","en":"I wonder if he's arrived yet."}],"id":"n4g91"},{"pattern":"〜さ","meaning":"-ness (turns adjectives into nouns)","formation":"い-adjective (drop い) + さ; な-adjective + さ","note":"Expresses a degree or measurable quality: 高さ (height), 大切さ (importance). いい → よさ.","examples":[{"ja":"この{箱|はこ}の重さはどのくらいですか。","en":"How heavy is this box?"},{"ja":"東京の夏の暑さにはまだ{慣|な}れません。","en":"I'm still not used to the heat of Tokyo summers."},{"ja":"病気になって、{健康|けんこう}の大切さがわかりました。","en":"Getting sick made me realize the importance of health."}],"id":"n4g92"},{"pattern":"〜のは / 〜のが / 〜のを","meaning":"nominalizer: turns a verb phrase into a noun (doing ...)","formation":"Plain form + の + は / が / を; な-adjective + な + の","note":"Common with 好き, 上手, 忘れる. With perception verbs (見る, 聞こえる) use の, not こと.","examples":[{"ja":"私は{絵|え}を{描|か}くのが好きです。","en":"I like drawing pictures."},{"ja":"{子供|こども}たちが{遊|あそ}んでいるのを見ました。","en":"I watched the children playing."},{"ja":"日本語で話すのは{難|むずか}しいです。","en":"Speaking in Japanese is difficult."}],"id":"n4g93"},{"pattern":"〜ばかり","meaning":"nothing but; only; always","formation":"Noun + ばかり; Verb て-form + ばかりいる","note":"Often critical: doing one thing too much. 〜てばかりいる = 'do nothing but ...'.","examples":[{"ja":"弟はゲームばかりしています。","en":"My little brother does nothing but play games."},{"ja":"肉ばかり食べないで、野菜も食べなさい。","en":"Don't eat only meat; eat your vegetables too."},{"ja":"{彼|かれ}は{寝|ね}てばかりいる。","en":"He does nothing but sleep."}],"id":"n4g94"},{"pattern":"〜しか〜ない","meaning":"only; nothing but (with a negative)","formation":"Noun (+ particle) + しか + negative verb","note":"Always used with a negative verb and stresses 'no more than'. Replaces が / を. Compare neutral だけ.","examples":[{"ja":"{財布|さいふ}に千円しかありません。","en":"I only have 1,000 yen in my wallet."},{"ja":"朝はコーヒーしか飲まない。","en":"In the morning I only drink coffee."},{"ja":"この店は土曜日しか開いていません。","en":"This shop is only open on Saturdays."}],"id":"n4g95"},{"pattern":"Number + も (emphasis)","meaning":"as many as; as much as; a whole ...","formation":"Number + counter + も","note":"Shows the amount feels large to the speaker. With a negative (一つも〜ない) it means 'not even one'.","examples":[{"ja":"駅で一時間も待ちました。","en":"I waited at the station for a whole hour."},{"ja":"{彼|かれ}は車を三台も持っている。","en":"He owns as many as three cars."},{"ja":"漢字が一つも書けません。","en":"I can't write even one kanji."}],"id":"n4g96"},{"pattern":"〜ほど〜ない","meaning":"not as ... as","formation":"Noun + ほど + negative adjective / verb","note":"A is not up to B's level. Always followed by a negative predicate.","examples":[{"ja":"今年の冬は去年ほど寒くないです。","en":"This winter isn't as cold as last year."},{"ja":"私は兄ほど{背|せ}が高くない。","en":"I'm not as tall as my older brother."},{"ja":"日本語は思ったほど{難|むずか}しくなかった。","en":"Japanese wasn't as difficult as I thought."}],"id":"n4g97"},{"pattern":"〜でも (... or something)","meaning":"... or something (soft suggestion)","formation":"Noun + でも","note":"Softens a suggestion by offering an example. Replaces が / を.","examples":[{"ja":"お茶でも飲みませんか。","en":"Would you like some tea or something?"},{"ja":"{週末|しゅうまつ}、映画でも見に行こうか。","en":"Shall we go see a movie or something this weekend?"},{"ja":"{暇|ひま}なら、本でも読んだら？","en":"If you're bored, why not read a book or something?"}],"id":"n4g98"},{"pattern":"いつでも / 何でも / どこでも","meaning":"any (time / thing / place) at all","formation":"Question word + でも","note":"Used with affirmative predicates. Contrast question word + も + negative (何も〜ない = nothing).","examples":[{"ja":"いつでも電話してください。","en":"Please call me anytime."},{"ja":"私は何でも食べます。","en":"I'll eat anything."},{"ja":"このカードはどこでも使えます。","en":"This card can be used anywhere."}],"id":"n4g99"},{"pattern":"〜とか〜とか","meaning":"things like ... and ... (casual listing)","formation":"Noun / plain form + とか + Noun / plain form + とか","note":"A casual version of 〜や〜など. Can also list actions.","examples":[{"ja":"休みの日は{掃除|そうじ}とか{洗濯|せんたく}とかをします。","en":"On my days off I do things like cleaning and laundry."},{"ja":"{果物|くだもの}なら、りんごとかバナナとかが好きです。","en":"As for fruit, I like things like apples and bananas."},{"ja":"もっと運動するとか、早く{寝|ね}るとかしたほうがいいよ。","en":"You should do things like exercise more or go to bed earlier."}],"id":"n4g100"},{"pattern":"〜によると","meaning":"according to","formation":"Noun + によると","note":"Names the source of information. The sentence usually ends with そうだ or らしい.","examples":[{"ja":"ニュースによると、{昨日|きのう}大きい{地震|じしん}があったそうです。","en":"According to the news, there was a big earthquake yesterday."},{"ja":"{天気予報|てんきよほう}によると、今夜は雨らしい。","en":"According to the forecast, it's going to rain tonight."},{"ja":"{友達|ともだち}の話によると、あの店は{閉|し}まったそうです。","en":"According to my friend, that shop has closed."}],"id":"n4g101"},{"pattern":"〜について","meaning":"about; concerning","formation":"Noun + について; Noun + についての + Noun","note":"Marks the topic of talking, thinking, writing or research. Before a noun: についての.","examples":[{"ja":"日本の{文化|ぶんか}について{調|しら}べています。","en":"I'm researching Japanese culture."},{"ja":"{将来|しょうらい}について{両親|りょうしん}と話しました。","en":"I talked with my parents about my future."},{"ja":"京都の{歴史|れきし}についての本を読みました。","en":"I read a book about the history of Kyoto."}],"id":"n4g102"},{"pattern":"〜にする (decide on)","meaning":"to decide on; to choose","formation":"Noun + にする","note":"Used for choices, such as ordering food. Compare 〜ことにする (decide to do something).","examples":[{"ja":"私はコーヒーにします。","en":"I'll have coffee."},{"ja":"{会議|かいぎ}は月曜日にしましょう。","en":"Let's have the meeting on Monday."},{"ja":"{誕生日|たんじょうび}のプレゼントは何にする？","en":"What should we get for the birthday present?"}],"id":"n4g103"},{"pattern":"〜くする / 〜にする (make)","meaning":"to make (something) ...","formation":"い-adjective (drop い) + くする; な-adjective / Noun + にする","note":"Someone intentionally changes something. Compare 〜くなる / 〜になる (something becomes).","examples":[{"ja":"テレビの音を小さくしてください。","en":"Please turn the TV down."},{"ja":"{部屋|へや}をきれいにしました。","en":"I tidied up the room."},{"ja":"{髪|かみ}を短くしたいです。","en":"I want to cut my hair short."}],"id":"n4g104"},{"pattern":"〜出す","meaning":"to suddenly start doing","formation":"Verb ます-stem + 出す","note":"A sudden or unexpected start, often outside one's control. For planned starts, use 〜始める.","examples":[{"ja":"急に雨が{降|ふ}り出した。","en":"It suddenly started raining."},{"ja":"赤ちゃんが{泣|な}き出しました。","en":"The baby burst into tears."},{"ja":"{彼|かれ}は急に{笑|わら}い出した。","en":"He suddenly burst out laughing."}],"id":"n4g105"},{"pattern":"〜始める","meaning":"to begin doing","formation":"Verb ます-stem + 始める","note":"A neutral start of an action or process; works with intentional actions, unlike 〜出す.","examples":[{"ja":"去年から日本語を習い始めました。","en":"I started learning Japanese last year."},{"ja":"{桜|さくら}が{咲|さ}き始めた。","en":"The cherry blossoms have started to bloom."},{"ja":"食べ始める前に「いただきます」と言います。","en":"Before starting to eat, we say 'itadakimasu'."}],"id":"n4g106"},{"pattern":"〜終わる","meaning":"to finish doing","formation":"Verb ます-stem + 終わる","note":"Shows an action is completed. Conjugates as a u-verb (読み終わった).","examples":[{"ja":"この本はもう読み終わりました。","en":"I've already finished reading this book."},{"ja":"食べ終わったら、お{皿|さら}を洗ってね。","en":"When you've finished eating, wash the dishes, okay?"},{"ja":"レポートを書き終わるまで{寝|ね}られない。","en":"I can't go to bed until I finish writing the report."}],"id":"n4g107"},{"pattern":"〜{続|つづ}ける","meaning":"to continue doing; to keep doing","formation":"Verb ます-stem + 続ける","note":"Shows an action continues over time. Conjugates as a ru-verb.","examples":[{"ja":"三時間歩き{続|つづ}けました。","en":"I kept walking for three hours."},{"ja":"赤ちゃんは一日中{泣|な}き{続|つづ}けた。","en":"The baby kept crying all day."},{"ja":"これからも日本語を勉強し{続|つづ}けたいです。","en":"I want to keep studying Japanese from now on, too."}],"id":"n4g108"},{"pattern":"〜ばいい / 〜たらいい","meaning":"should; it would be good to (asking for advice); I hope","formation":"Verb ば-form + いい; Verb た-form + らいい","note":"〜ばいいですか / 〜たらいいですか asks 'what should I do?'. With な(あ) it expresses a wish: 晴れればいいなあ.","examples":[{"ja":"駅までどうやって行けばいいですか。","en":"How should I get to the station?"},{"ja":"何を持っていったらいいですか。","en":"What should I bring?"},{"ja":"明日、{晴|は}れればいいなあ。","en":"I hope it's sunny tomorrow."}],"id":"n4g109"},{"pattern":"〜{必要|ひつよう}がある","meaning":"it is necessary to; need to","formation":"Verb dictionary form + 必要がある; negative: 必要はない","note":"More formal and objective than 〜なければならない. 〜必要はない means 'there's no need to'.","examples":[{"ja":"ビザを{取|と}る{必要|ひつよう}があります。","en":"You need to get a visa."},{"ja":"{予約|よやく}する{必要|ひつよう}はありません。","en":"There's no need to make a reservation."},{"ja":"もう一度{調|しら}べる{必要|ひつよう}があります。","en":"We need to check it once more."}],"id":"n4g110"},{"pattern":"〜おきに","meaning":"every other; at intervals of","formation":"Number + counter + おきに","note":"一日おきに = every other day. With minutes or distances it usually just means 'every' (十五分おきに).","examples":[{"ja":"一日おきにジムへ行きます。","en":"I go to the gym every other day."},{"ja":"バスは十五分おきに来ます。","en":"The bus comes every fifteen minutes."},{"ja":"道には二メートルおきに木が{植|う}えてあります。","en":"Trees are planted every two meters along the road."}],"id":"n4g111"}];